CREATE TABLE peg_retention_classes (
 workspace_id TEXT NOT NULL,class TEXT NOT NULL,days INTEGER CHECK(days IS NULL OR days BETWEEN 1 AND 36500),
 updated_at INTEGER NOT NULL,updated_by TEXT NOT NULL,PRIMARY KEY(workspace_id,class)
);
CREATE TABLE peg_data_holds (
 id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,target_type TEXT NOT NULL,target_id TEXT NOT NULL,
 authority TEXT NOT NULL,expires_at INTEGER NOT NULL,created_by TEXT NOT NULL,created_at INTEGER NOT NULL,released_at INTEGER
);
CREATE TABLE peg_data_receipts (
 id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,actor_id TEXT NOT NULL,target_type TEXT NOT NULL,target_id TEXT NOT NULL,
 at INTEGER NOT NULL,outcome TEXT NOT NULL,counts TEXT NOT NULL,retained TEXT NOT NULL,external_limits TEXT NOT NULL
);
CREATE TRIGGER peg_data_receipts_no_update BEFORE UPDATE ON peg_data_receipts BEGIN SELECT RAISE(ABORT,'receipt_append_only'); END;
CREATE TRIGGER peg_data_receipts_no_delete BEFORE DELETE ON peg_data_receipts BEGIN SELECT RAISE(ABORT,'receipt_append_only'); END;
CREATE TABLE peg_data_erased_objects (object_type TEXT NOT NULL,object_id TEXT NOT NULL,erased_at INTEGER NOT NULL,PRIMARY KEY(object_type,object_id));
CREATE TABLE peg_processor_policies (workspace_id TEXT NOT NULL,processor TEXT NOT NULL,approved INTEGER NOT NULL DEFAULT 0,training INTEGER NOT NULL DEFAULT 0,sharing INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(workspace_id,processor));
CREATE TABLE peg_data_revision (id INTEGER PRIMARY KEY CHECK(id=1),value INTEGER NOT NULL);
INSERT INTO peg_data_revision VALUES(1,1);
CREATE TABLE peg_data_guards (id TEXT PRIMARY KEY,revision INTEGER NOT NULL,actor_id TEXT NOT NULL,not_after INTEGER NOT NULL);
CREATE TRIGGER peg_data_check_guard BEFORE INSERT ON peg_data_guards BEGIN
 SELECT CASE WHEN NEW.revision<>(SELECT value FROM peg_data_revision WHERE id=1)
 OR NEW.not_after<=CAST((julianday('now')-2440587.5)*86400000 AS INTEGER)
 OR NOT EXISTS(SELECT 1 FROM oa_operators WHERE id=NEW.actor_id AND role='owner' AND status='active')
 THEN RAISE(ABORT,'stale_data_preview') END;
END;
CREATE TRIGGER peg_data_consume_guard AFTER INSERT ON peg_data_guards BEGIN DELETE FROM peg_data_guards WHERE id=NEW.id; END;
-- Immutable decisions stay immutable to ordinary doors. Only a reviewed owner erasure batch can remove its scoped rows.
CREATE TABLE peg_data_erasing_tasks (task_id TEXT PRIMARY KEY);
DROP TRIGGER peg_decisions_no_delete;
CREATE TRIGGER peg_decisions_no_delete BEFORE DELETE ON peg_task_decisions WHEN NOT EXISTS(SELECT 1 FROM peg_data_erasing_tasks WHERE task_id=OLD.task_id) BEGIN SELECT RAISE(ABORT,'immutable_decision'); END;
